namespace {
std::string friendly(std::string text){std::replace(text.begin(),text.end(),'_',' ');if(!text.empty())text[0]=char(std::toupper(static_cast<unsigned char>(text[0])));if(text.starts_with("Debugger "))text.erase(0,9);return text;}
std::string categoryFor(const std::string& name){
 if(name.starts_with("debugger_"))return "Debugger";
 if(name=="undo"||name=="redo"||name.find("analysis_database")!=std::string::npos||name.find("analysis_cache")!=std::string::npos||name=="get_undo_history")return "Database";
 if(name.find("library_signature")!=std::string::npos||name=="identify_libraries")return "Libraries";
 if(name.find("debug_symbols")!=std::string::npos||name=="lookup_source_line")return "Symbols";
 if(name=="define_type"||name=="delete_type"||name=="list_types"||name=="import_c_header"||name.find("type_library")!=std::string::npos)return "Types";
 if(name.find("pseudocode")!=std::string::npos||name.find("local_variable")!=std::string::npos||name.find("call_site")!=std::string::npos||name=="rename_variable"||name=="set_indirect_call_target"||name=="mark_multistage_jump")return "Pseudocode";
 if(name.find("script")!=std::string::npos||name.find("plugin")!=std::string::npos)return "Extensions";
 static const std::set<std::string> manual={"define_code","define_data","clear_definition","get_manual_analysis","create_function","delete_function","set_function_bounds","split_function","merge_functions","set_operand_presentation","clear_operand_presentation","define_switch_table","remove_switch_table","edit_segment","rebase_binary"};
 if(manual.contains(name))return "Corrections";
 if(name.find("analysis")!=std::string::npos||name=="analyze"||name=="get_control_flow"||name=="get_cross_references"||name=="analyze_reachable"||name=="discover_reachable_functions"||name=="recover_switch_table"||name=="get_architectures"||name=="open_binary_architecture")return "Analysis";
 return {};
}
bool required(const Json& schema,const std::string& key){if(!schema.contains("required"))return false;return std::find(schema["required"].begin(),schema["required"].end(),Json(key))!=schema["required"].end();}
}
void WorkspaceLayout::load(const std::filesystem::path& path){settings=path;try{std::ifstream file(path);if(!file)return;Json data;file>>data;navigator=std::clamp(data.value("navigator",270.f),180.f,600.f);inspector=std::clamp(data.value("inspector",285.f),180.f,600.f);previewFraction=std::clamp(data.value("preview_fraction",.38f),.2f,.7f);showInspector=data.value("show_inspector",true);splitPreview=data.value("split_preview",false);auto value=data.value("preview",std::string("Pseudocode"));if(value=="Pseudocode"||value=="Disassembly")preview=value;}catch(...){}}
void WorkspaceLayout::save()const{if(settings.empty())return;try{std::filesystem::create_directories(settings.parent_path());auto temporary=settings;temporary+=L".tmp";{std::ofstream out(temporary);out<<Json{{"navigator",navigator},{"inspector",inspector},{"preview_fraction",previewFraction},{"show_inspector",showInspector},{"split_preview",splitPreview},{"preview",preview}}.dump(2);if(!out)return;}std::error_code ec;std::filesystem::remove(settings,ec);std::filesystem::rename(temporary,settings,ec);}catch(...){}}
void WorkspaceLayout::splitter(const char* id,float height,float& width,bool reverse){ImGui::SameLine(0,3);ImGui::InvisibleButton(id,{6,height});if(ImGui::IsItemHovered()||ImGui::IsItemActive())ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeEW);if(ImGui::IsItemActive()){width=std::clamp(width+ImGui::GetIO().MouseDelta.x*(reverse?-1.f:1.f),180.f,600.f);if(ImGui::IsMouseReleased(ImGuiMouseButton_Left))save();}if(ImGui::IsItemDeactivated())save();auto p=ImGui::GetItemRectMin(),q=ImGui::GetItemRectMax();ImGui::GetWindowDrawList()->AddRectFilled(p,q,ImGui::IsItemHovered()?IM_COL32(81,147,139,255):IM_COL32(24,36,43,255),3);ImGui::SameLine(0,3);}
void WorkbenchView::choose(const Json& definition,Address selected){operation=definition.at("name");fields.clear();error.clear();auto& schema=definition.at("inputSchema");for(auto it=schema["properties"].begin();it!=schema["properties"].end();++it){auto& field=fields[it.key()];field.included=required(schema,it.key());std::string initial;if(it.key()=="address")initial=hex(selected);else if(it.key()=="path")initial="D:/Scratcher/";else if(it->contains("default")){if((*it)["default"].is_string())initial=(*it)["default"];else initial=(*it)["default"].dump();}else if(it->contains("enum")&&!(*it)["enum"].empty())initial=((*it)["enum"][0].is_string()?(*it)["enum"][0].get<std::string>():(*it)["enum"][0].dump());else if(it->value("type",std::string())=="integer")initial=std::to_string(std::max<uint64_t>(1,it->value("minimum",uint64_t(0))));else if(it->value("type",std::string())=="array")initial="[]";else if(it->value("type",std::string())=="object")initial="{}";strncpy_s(field.input.data(),field.input.size(),initial.c_str(),_TRUNCATE);}}
void WorkbenchView::update(const std::string& name,const Json& data){if(!categoryFor(name).empty()){result=data;resultText=data.dump(2);}}
void WorkbenchView::draw(const Json& definitions,Address selected,bool busy,ImFont* mono){
 ImGui::TextColored({.4f,.89f,.76f,1},"Workbench");ImGui::SameLine();ImGui::TextDisabled("Selected address: %s",hex(selected).c_str());
 if(ImGui::BeginTabBar("workbench_categories",ImGuiTabBarFlags_FittingPolicyScroll)){bool requested=category!=renderedCategory;for(const char* title:{"Analysis","Corrections","Types","Symbols","Libraries","Pseudocode","Database","Debugger","Extensions"})if(ImGui::BeginTabItem(title,nullptr,requested&&category==title?ImGuiTabItemFlags_SetSelected:0)){if(category!=title&&!requested){category=title;operation.clear();fields.clear();}renderedCategory=title;ImGui::EndTabItem();}ImGui::EndTabBar();}
 std::vector<const Json*> choices;for(const auto& definition:definitions)if(categoryFor(definition.at("name"))==category)choices.push_back(&definition);
 if(choices.empty()){ImGui::TextWrapped("No operations are registered in this category.");return;}
 auto current=std::find_if(choices.begin(),choices.end(),[&](const Json* d){return d->at("name")==operation;});if(current==choices.end()){choose(*choices.front(),selected);current=choices.begin();}
 ImGui::SetNextItemWidth(std::min(420.f,ImGui::GetContentRegionAvail().x));if(ImGui::BeginCombo("Operation",friendly(operation).c_str())){for(const auto* definition:choices){auto name=definition->at("name").get<std::string>();if(ImGui::Selectable(friendly(name).c_str(),name==operation))choose(*definition,selected);}ImGui::EndCombo();}
 current=std::find_if(choices.begin(),choices.end(),[&](const Json* d){return d->at("name")==operation;});const auto& definition=**current;const auto& schema=definition.at("inputSchema");
 if(category=="Debugger"){ImGui::BeginDisabled(busy);for(auto pair:{std::pair{"Status","debugger_status"},std::pair{"Pause","debugger_pause"},std::pair{"Continue","debugger_continue"},std::pair{"Step","debugger_step"},std::pair{"Registers","debugger_registers"},std::pair{"Stack","debugger_stack"}}){if(ImGui::SmallButton(pair.first))run(pair.second,Json::object());ImGui::SameLine();}ImGui::NewLine();ImGui::EndDisabled();if(operation=="debugger_launch")ImGui::TextWrapped("Launch executes the chosen program under the debugger.");}
 ImGui::BeginChild("workbench_form",{0,std::min(310.f,ImGui::GetContentRegionAvail().y*.5f)},ImGuiChildFlags_Borders);
 if(operation=="import_c_header"&&!busy&&ImGui::Button("Load header file")){wchar_t path[32768]{};OPENFILENAMEW of{};of.lStructSize=sizeof(of);of.lpstrFile=path;of.nMaxFile=32768;of.lpstrFilter=L"C headers\0*.h;*.hpp\0All files\0*.*\0";of.Flags=OFN_FILEMUSTEXIST|OFN_NOCHANGEDIR;if(GetOpenFileNameW(&of)){try{std::ifstream file(std::filesystem::path(path),std::ios::binary);file.seekg(0,std::ios::end);auto size=file.tellg();if(size<=0||size>262144)throw std::runtime_error("Choose a header of at most 256 KiB");file.seekg(0);auto& field=fields["text"];field.input.resize(size_t(size)+1);file.read(field.input.data(),size);if(!file)throw std::runtime_error("Cannot read header");field.input[size_t(size)]=0;field.included=true;}catch(const std::exception& ex){error=ex.what();}}}
 for(auto it=schema["properties"].begin();it!=schema["properties"].end();++it){auto& field=fields[it.key()];auto label=friendly(it.key());ImGui::PushID(it.key().c_str());bool mandatory=required(schema,it.key());if(!mandatory){ImGui::Checkbox("##include",&field.included);ImGui::SameLine();}ImGui::BeginDisabled(busy||!field.included);auto type=it->value("type",std::string("string"));ImGui::SetNextItemWidth(-1);
  if(type=="boolean")ImGui::Checkbox(label.c_str(),&field.boolean);
  else if(it->contains("enum")){ImGui::TextUnformatted(label.c_str());if(ImGui::BeginCombo("##enum",field.input.data())){for(auto& option:(*it)["enum"]){auto text=option.is_string()?option.get<std::string>():option.dump();if(ImGui::Selectable(text.c_str(),text==field.input.data()))strncpy_s(field.input.data(),field.input.size(),text.c_str(),_TRUNCATE);}ImGui::EndCombo();}}
  else {ImGui::TextUnformatted(label.c_str());bool multiline=it.key()=="text"||it.key()=="declaration"||type=="array"||type=="object";if(multiline)ImGui::InputTextMultiline("##input",field.input.data(),field.input.size(),{-1,100});else ImGui::InputText("##input",field.input.data(),field.input.size());if(it.key()=="address"){ImGui::SameLine();if(ImGui::SmallButton("Use selection"))strncpy_s(field.input.data(),field.input.size(),hex(selected).c_str(),_TRUNCATE);}}
  ImGui::EndDisabled();ImGui::PopID();}
 ImGui::EndChild();ImGui::BeginDisabled(busy);if(ImGui::Button(friendly(operation).c_str())){try{Json args=Json::object();for(auto it=schema["properties"].begin();it!=schema["properties"].end();++it){auto& field=fields[it.key()];if(!field.included)continue;auto type=it->value("type",std::string("string"));if(type=="boolean")args[it.key()]=field.boolean;else if(type=="integer"||type=="number"||type=="array"||type=="object"){auto value=Json::parse(field.input.data());if(type=="integer"&&!value.is_number_integer())throw std::runtime_error(friendly(it.key())+" must be an integer");args[it.key()]=std::move(value);}else args[it.key()]=field.input.data();}error.clear();run(operation,std::move(args));}catch(const std::exception& ex){error=ex.what();}}ImGui::EndDisabled();if(!error.empty())ImGui::TextWrapped("%s",error.c_str());ImGui::SameLine();if(ImGui::SmallButton("Copy result"))ImGui::SetClipboardText(resultText.c_str());ImGui::Separator();
 ImGui::BeginChild("workbench_results",{0,0},ImGuiChildFlags_None,ImGuiWindowFlags_HorizontalScrollbar);ImGui::PushFont(mono,15.f);if(result.is_object()&&result.contains("items")&&result["items"].is_array()){for(auto& item:result["items"]){if(item.is_object()&&item.contains("address")&&item["address"].is_string()){auto at=item["address"].get<std::string>();if(ImGui::Selectable((at+"##result"+item.dump()).c_str(),false,ImGuiSelectableFlags_AllowDoubleClick)&&ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left))jump(address(Json(at)));ImGui::SameLine();}ImGui::TextUnformatted(item.dump().c_str());}}else ImGui::TextUnformatted(resultText.c_str());ImGui::PopFont();ImGui::EndChild();
}
